/* Demand-first private employee demo. Local intent parsing and illustrative assets; no model or business API calls. */
const privateAgent={send:{request:'',brief:null,revision:0,confirmedRevision:null,savedId:null,error:'',edit:''},query:{request:'',summary:'',error:''},groups:{request:'',summary:'',error:''}};
const legacyPrivate={statistics:statisticsWorkspace,groups:groupsWorkspace,qa:qaWorkspace,context:privateContext,changeCorp:changePrivateCorp,viewDraft:viewSendDraft,right:renderPrivateRight,customers:demoCustomers};
demoCustomers=function(){return legacyPrivate.customers().map((c,i)=>({...c,lastVisitDays:[5,40,12,60,25,90][i%6]}))};
function paToday(now=new Date()){return new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}).format(now)}
function paDateOffset(days,today=paToday()){let d=new Date(today+'T00:00:00+08:00');d.setUTCDate(d.getUTCDate()+days);return paToday(d)}
function paWhen(text,today=paToday()){let relative=[...text.matchAll(/后天|明天|明早|明晚|今天|今晚/g)].pop();let offset=relative?.[0]==='后天'?2:/明天|明早|明晚/.test(relative?.[0]||'')?1:0;let day=paDateOffset(offset,today),specified=!!relative;let explicit=[...text.matchAll(/(20\d{2})[-年/](\d{1,2})[-月/](\d{1,2})日?/g)].pop();if(explicit&&(!relative||explicit.index>relative.index)){day=explicit[1]+'-'+explicit[2].padStart(2,'0')+'-'+explicit[3].padStart(2,'0');specified=true}let match=[...text.matchAll(/(上午|下午|晚上|今晚|中午|早上)?\s*(\d{1,2})[:：点时](\d{1,2})?/g)].pop(),hour=/晚上|今晚|明晚/.test(text)?20:/下午/.test(text)?15:10,minute=0;if(match){hour=Number(match[2]);minute=Number(match[3]||0);if(/下午|晚上|今晚/.test(match[1]||'')&&hour<12)hour+=12;specified=true}if(!specified){day=paDateOffset(1,today)}let invalid=hour<9||hour>21||minute>59||hour===21&&minute>0;let value=day+'T'+String(hour).padStart(2,'0')+':'+String(minute).padStart(2,'0');if(!specified&&new Date(value+'+08:00')<new Date())value=paDateOffset(1,today)+'T10:00';return {value,suggested:!specified,invalid,past:new Date(value+'+08:00').getTime()<Date.now()}}
function paFocusResult(selector){if(typeof requestAnimationFrame==='function')requestAnimationFrame(()=>document.querySelector(selector)?.scrollIntoView?.({behavior:'smooth',block:'start'}))}
function paUnknownStation(text){return [...text.matchAll(/[\u4e00-\u9fa5]{1,12}?(?:店|油站)/g)].some(m=>!/(?:未到店|到店|门店)$/.test(m[0])&&!demoCorp().stations.some(n=>m[0].includes(n)||m[0].includes(n.replace('店',''))))}
function paPlan(request,corpId=privateState.corp,today=paToday()){let corp=demoCorp(),latest=request.split('调整要求：').pop(),stationText=corp.stations.some(n=>latest.includes(n)||latest.includes(n.replace('店','')))?latest:request,stationNames=corp.stations.filter(n=>stationText.includes(n)||stationText.includes(n.replace('店',''))),outside=/(东城|西城|南湖|滨江|城北|湖畔)/.test(request)&&!stationNames.length;let purpose=/召回|未到店|流失|沉睡/.test(request)?'客户召回':/会员|权益/.test(request)?'会员关怀':/营业|时间调整/.test(request)?'营业提醒':/价格|油价/.test(request)?'价格提醒':'活动提醒';let days=request.match(/(?:超过|近|流失|沉睡|未到店)?\s*(\d+)\s*天/),lastVisit=/未到店|召回|沉睡/.test(request),tag=/新客户|新增客户/.test(request)?'新客户':/活动关注/.test(request)?'活动关注':'';let excluded=/排除.*(?:参与|参加)|不要.*(?:参与|参加)/.test(request),unsupported=[];
if(/客户群|群里|群聊|朋友圈|短信/.test(request)&&!/不要发群|不是群聊/.test(request))unsupported.push('当前入口是客户 1 对 1 私聊，需求提到了其他渠道，请修改为客户私聊或使用对应能力。');if(/未绑定|全部.*(?:含|包括).*未绑定/.test(request))unsupported.push('当前自动触达仅使用已绑定客户，无法纳入未绑定客户。');if(outside)unsupported.push('需求中的门店不在当前示例企业范围内，请调整门店或切换企业。');if(/购买|消费金额|客单价|充值|余额|生日|手机号|车牌|油品偏好|高价值|购买过/.test(request))unsupported.push('需求包含尚未配置的客户画像条件，暂不能计算范围；需要接入相应业务字段。');if(/流失/.test(request)&&!/未到店/.test(request))unsupported.push('“流失客户”需要明确流失口径，不能自动等同于未到店客户。');
if(!/发|提醒|通知|触达|召回|会员|客户|营销|活动|海报|权益/.test(request))unsupported.push('请描述客户触达需求，例如给会员发提醒、做召回或准备活动海报。');if(paUnknownStation(stationText))unsupported.push('无法在当前企业定位你提到的门店，请核对门店名称；不会自动扩大到其他门店。');let namedStaff=demoStaff().filter(e=>request.includes(e.name)),gender=/女|女性/.test(request)?'女':/男|男性/.test(request)?'男':'';if(/VIP|高价值|高净值|高级会员/.test(request))unsupported.push('需求中的会员分层尚未配置，请明确可用的人群条件。');if(/员工[甲乙丙丁]/.test(request)&&!namedStaff.length)unsupported.push('无法匹配你指定的员工，不会扩大到其他员工。');if(/排除|不要/.test(request)&&!excluded&&!/不要发群|不是群聊/.test(request))unsupported.push('未能识别排除条件，请用已配置的人群条件明确说明。');let people=demoCustomers().filter(c=>c.bound&&(!namedStaff.length||namedStaff.some(e=>e.id===c.staff))&&(!gender||c.gender===gender)&&(!stationNames.length||stationNames.includes(c.station))&&(!tag||c.tags.includes(tag))&&(!lastVisit||c.lastVisitDays>=Number(days?.[1]||30))&&(!excluded||!c.tags.includes('已参与活动')));if(unsupported.length)people=[];let when=paWhen(request,today);if(when.invalid)unsupported.push('发送时刻不在本页示例时段 09:00–21:00 内，请调整后确认。');if(when.past)unsupported.push('识别到的发送时间已过，请改为未来时间。');let risk=[];if(!when.suggested&&!/20\d{2}|明天|明早|明晚|后天|今天|今晚/.test(request))risk.push('只描述了时刻，默认按今天理解，请核对确切日期。');if(!/优惠|立减|满\d|折|赠|券/.test(request))risk.push('未提供具体优惠权益，文案采用通用关怀表达，不添加优惠数字。');else risk.push('优惠和权益来自你的描述，尚未核实活动资料；当前示例文案不加入价格或优惠数字。');risk.push('海报为预置演示素材，正式接入后将根据活动事实生成或复用。');
let place=stationNames.length?stationNames.join('、'):corp.stations.join('、');let copy=purpose==='客户召回'?`好久不见，期待再次为您服务。${place}持续为会员提供便捷、贴心的到店服务，欢迎您在方便时回来看看。具体活动与使用条件请以门店说明为准。`:purpose==='营业提醒'?`${place}为您送上一份到店提醒。营业时间与服务安排请以门店最新公告为准，出行前欢迎联系门店了解详情。`:purpose==='价格提醒'?`${place}为您送上价格信息提醒。具体油品价格、执行时间与适用条件请以门店最新公示为准，欢迎到店咨询。`:`您好，${place}为您送上会员关怀与活动提醒。欢迎到店了解最新服务与会员权益，具体活动时间、适用范围和使用条件请以门店说明为准。`;
let rule='已绑定客户'+(namedStaff.length?'，归属'+namedStaff.map(e=>e.name).join('、'):'')+(gender?'，性别为'+gender:'')+(lastVisit?'，最近 '+(days?.[1]||30)+' 天未到店':'')+(tag?'，标签为“'+tag+'”':'')+(excluded?'，排除已参与活动客户':'');let employees=[...new Set(people.map(c=>c.staff))];return {corp:corpId,request,purpose,title:purpose+' · 客户私聊方案',copy,stationNames:stationNames.length?stationNames:corp.stations.slice(),rule,people,employees,sendTime:when.value,timeSuggested:when.suggested,risks:risk,issues:unsupported,poster:'assets/private-member-poster.png',posterSource:'预置示例海报 · 非本次实时生成',createdAt:today}}
function paInput(title,desc,request,examples,action,placeholder,id){return `<div class="pa-request"><div class="pa-agent-heading"><div class="avatar">${icon('sparkles')}</div><div><h2>${title}</h2><p>${desc}</p></div><span class="pa-agent-label">私域数字员工</span></div><textarea id="${id}" aria-label="${placeholder}" placeholder="${placeholder}" maxlength="2000">${esc(request)}</textarea><div class="pa-request-footer"><span>${icon('paperclip')} ${current==='send'?'无需先准备员工名单、文案或海报':'直接提问，自动整理查询范围与口径'}</span><button class="primary" onclick="${action}()">${icon('sparkles')} ${current==='send'?'生成完整预览':current==='qa'?'回答问题':'理解需求并查询'}</button></div><div class="pa-examples"><span>试着说</span>${examples.map((x,i)=>`<button data-pa-example="${i}" onclick="document.getElementById('${id}').value=this.textContent;document.getElementById('${id}').focus()">${esc(x)}</button>`).join('')}</div></div>`}
privateContext=function(){return `<div class="pa-context"><span>${icon('building-2')} 已绑定企业：<b>${demoCorp().name}</b></span><details><summary>切换企业</summary>${legacyPrivate.context()}</details><span class="pa-demo-badge">演示环境</span></div>`};
changePrivateCorp=function(value){if(value===privateState.corp)return;privateAgent.send={request:'',brief:null,revision:0,confirmedRevision:null,savedId:null,error:'',edit:''};privateAgent.query={request:'',summary:'',error:''};privateAgent.groups={request:'',summary:'',error:''};legacyPrivate.changeCorp(value)};
sendWorkspace=function(){let s=privateAgent.send;return `${paInput('告诉我，这次想怎样触达客户？','我来整理推送人群、文案、海报与时间，你只需要看预览、做确认。',s.request,['明天上午10点给滨江店会员发关怀提醒，配一张海报','明晚给30天未到店的会员发召回消息','给所有已绑定会员发周末提醒，排除已参与活动的客户'],'generatePrivatePlan','例如：明天给30天未到店的会员发一条召回消息，帮我配好海报和文案。','paSendRequest')}${s.error?`<div class="video-error" role="alert">${esc(s.error)}</div>`:''}${s.brief?paPreview():`<div class="pa-autowork"><div class="pa-empty-icon">${icon('wand-sparkles')}</div><h3>一句需求，准备好一整套触达方案</h3><p>人群自动匹配，员工按客户归属关联，文案和图片在同一页预览。</p><div class="pa-output-list">${[['users-round','推送范围','会员画像与门店范围'],['file-text','消息文案','客户收到的完整内容'],['image','海报 / 图片','素材预览与来源'],['calendar-clock','发送安排','确切时间与执行范围']].map(([ic,t,d])=>`<div>${icon(ic)}<strong>${t}</strong><small>${d}</small></div>`).join('')}</div></div>`}<div class="pa-footnote">当前为本地交互原型：语义规则匹配与预置素材演示，不调用真实模型或业务服务。</div>`};
function generatePrivatePlan(text){let s=privateAgent.send,request=typeof text==='string'?text:$('#paSendRequest').value.trim();if(!request.trim()){s.error='请先说一句你想完成的事情。';render();return}if(request.length>2000){s.error='需求请控制在 2000 字以内。';render();return}s.request=request;s.brief=paPlan(request);s.revision++;s.confirmedRevision=null;s.savedId=null;s.error='';privateLog('按一句话需求准备触达预览（示例），未发送');render();paFocusResult('.pa-preview')}
function paPreview(){let s=privateAgent.send,b=s.brief,confirmed=s.confirmedRevision===s.revision;return `<section class="pa-preview"><div class="pa-preview-heading"><div><div class="eyebrow">YOUR PREVIEW</div><h3>整套方案已准备好，请看一下</h3></div><span id="paVersionStatus" class="state-chip ${confirmed?'':'amber'}">${confirmed?'此版本已确认':'等待你的确认'}</span></div><div class="pa-prepared"><span>${icon('check')} 需求已整理</span><span>${icon(b.people.length?'check':'circle-help')} ${b.people.length?'范围已匹配':'范围待核对'}</span><span>${icon('check')} 内容已准备</span></div>${b.issues.length?`<div class="video-warning"><strong>有 ${b.issues.length} 项需要调整</strong><br>${b.issues.map(esc).join('<br>')}</div>`:''}<div class="pa-plan-summary"><div><small>推送给谁</small><strong>${esc(b.rule)}</strong><span>${esc(b.stationNames.join(' / '))}</span></div><div><small>示例匹配人数</small><strong>${b.people.length}<em> 位</em></strong><span>按归属自动关联 ${b.employees.length} 位员工</span></div><div><small>${b.timeSuggested?'建议发送时间':'识别的发送时间'}</small><strong>${esc(b.sendTime.replace('T',' '))}</strong><span>北京时间 · 最终确认前可调整</span></div></div><div class="pa-deliverables"><div class="pa-copy-panel"><div class="pa-subheading">${icon('message-circle')} 客户私聊预览 <span>1 对 1</span></div><div class="pa-phone-head"><div class="avatar">${icon('users-round')}</div><span>门店会员顾问</span></div><div class="pa-chat-message">${esc(b.copy)}</div><div class="pa-chat-attachment">${icon('image')} 会员服务海报 <small>与文字一起发送的图片示意</small></div></div><div class="pa-poster-panel"><div class="pa-subheading">${icon('image')} 海报 / 图片 <span>演示素材</span></div><button class="pa-poster-open" onclick="openPrivatePoster()" aria-label="放大海报预览"><img src="${b.poster}" alt="会员服务欢迎到店的示例海报"></button><small>${b.posterSource}</small></div></div><details class="pa-details"><summary>查看推送范围与自动执行详情</summary>${table(['关联员工','门店','示例匹配客户'],demoStaff().filter(e=>b.employees.includes(e.id)).map(e=>[e.name,e.station,b.people.filter(c=>c.staff===e.id).length+' 位']))}<p>员工按客户归属匹配，无需手动选择。范围仅使用当前企业内的已绑定示例客户；未绑定客户已剔除。</p></details><details class="pa-details"><summary>微调文案与发送时间</summary><div class="field"><label for="paCopyEdit">文案</label><textarea id="paCopyEdit" maxlength="2000" oninput="editPrivateBrief('copy',this.value)">${esc(b.copy)}</textarea></div><div class="field"><label for="paTimeEdit">发送时间 · 北京时间</label><input id="paTimeEdit" type="datetime-local" value="${esc(b.sendTime)}" onchange="editPrivateBrief('sendTime',this.value)"></div><small>修改后会取消此版本的确认，需要再次确认。</small></details><div class="pa-assumptions">${icon('info')} ${b.risks.map(esc).join(' ')}</div><div class="pa-revise"><label for="paAmend">想改哪里？直接告诉我</label><div><input id="paAmend" maxlength="800" value="${esc(s.edit)}" placeholder="例如：文案再短一点，改成后天下午3点"><button class="secondary" onclick="amendPrivatePlan()">调整预览</button></div></div><div class="pa-confirm"><div><strong>${confirmed?'已记录你的确认':'预览确认后，才进入下一步'}</strong><small>${confirmed?'已保存本地方案，未创建真实任务或发送消息。':'本次只确认示例方案，不会向真实客户发送消息。'}</small></div><button id="paConfirm" class="primary" onclick="confirmPrivatePlan()" ${b.issues.length||!b.people.length||!b.copy.trim()?'disabled':''}>${icon(confirmed?'file-check-2':'check-check')} ${confirmed?'查看已确认方案':'确认这版方案（演示）'}</button></div></section>`}
function editPrivateBrief(key,value){let s=privateAgent.send;if(!s.brief)return;s.brief[key]=value;s.revision++;s.confirmedRevision=null;s.savedId=null;if(key==='sendTime'){s.brief.issues=s.brief.issues.filter(x=>!x.includes('发送时间')&&!x.includes('发送时刻'));let time=value.split('T')[1];if(!value||!time||time<'09:00'||time>'21:00'||new Date(value+'+08:00')<=new Date())s.brief.issues.push('发送时间需要是未来的有效时刻，且位于示例时段 09:00–21:00 内。')}let btn=$('#paConfirm');if(btn){btn.disabled=!!s.brief.issues.length||!s.brief.people.length||!s.brief.copy.trim();btn.textContent='确认这版方案（演示）'}let badge=$('#paVersionStatus');if(badge){badge.textContent='等待你的确认';badge.classList.add('amber')}if(key==='sendTime'){render();return}renderPrivateRight();icons()}
function amendPrivatePlan(text){let s=privateAgent.send,edit=typeof text==='string'?text:$('#paAmend').value.trim();if(!edit){toast('请说一下要调整的内容');return}let previous=s.brief;if(!previous)return;let combined=s.request+'；调整要求：'+edit;generatePrivatePlan(combined);if(/短|简洁/.test(edit))privateAgent.send.brief.copy='好久不见，欢迎到'+privateAgent.send.brief.stationNames.join('、')+'了解会员服务。具体活动与条件以门店说明为准。';privateAgent.send.edit='';render()}
function confirmPrivatePlan(){let s=privateAgent.send,b=s.brief;if(!b||b.corp!==privateState.corp||b.issues.length||!b.people.length||!b.copy.trim()){toast('请先调整预览中的待补充事项');return}if(new Date(b.sendTime+'+08:00')<=new Date()){toast('发送时间已过，请调整后重新确认');return}if(s.confirmedRevision===s.revision&&s.savedId){viewSendDraft(s.savedId);return}let id='PA-'+Date.now()+'-'+privateState.drafts.length;privateState.drafts.push({id,corp:b.corp,corpName:demoCorp().name,name:b.title,count:b.people.length,scope:b.rule,staff:demoStaff().filter(e=>b.employees.includes(e.id)).map(e=>e.name).join('、'),text:b.copy,kind:'image',material:'会员服务海报 · 预置示例',sendTime:b.sendTime.replace('T',' ')+' · 北京时间',dryRun:true,cancelled:false,agent:true,poster:b.poster,request:b.request,version:s.revision});s.confirmedRevision=s.revision;s.savedId=id;privateLog('确认一句话方案 V'+s.revision+'，仅保存示例，未创建或发送真实任务');render();toast('方案已确认并保存（演示），未真实发送')}
function openPrivatePoster(){let b=privateAgent.send.brief;if(!b)return;modal(`<h2 id="modal-title">海报预览</h2><p>${b.posterSource}</p><img src="${b.poster}" alt="会员服务演示海报" style="display:block;width:min(100%,330px);margin:auto;border-radius:8px"><p>正式接入后将根据已确认活动事实生成或复用海报。</p>`)}
viewSendDraft=function(id){let d=privateState.drafts.find(x=>x.id===id);if(!d?.agent){legacyPrivate.viewDraft(id);return}modal(`<h2 id="modal-title">${esc(d.name)}</h2><p>${esc(d.corpName)} · V${d.version} · ${d.cancelled?'已取消示例':'已确认示例方案'}</p><div class="private-summary"><div class="kv"><span>推送范围</span><b>${esc(d.scope)}</b></div><div class="kv"><span>示例匹配人数</span><b>${d.count} 位</b></div><div class="kv"><span>自动关联员工</span><b>${esc(d.staff)}</b></div><div class="kv"><span>时间</span><b>${esc(d.sendTime)}</b></div></div><div class="pa-chat-message">${esc(d.text)}</div><img src="${d.poster}" alt="确认方案的示例海报" style="width:130px;border-radius:7px;margin-top:12px"><div class="notice">仅保存本地方案，未执行真实试运行、创建任务或发送。</div><div class="modal-footer">${d.cancelled?'':`<button class="secondary" onclick="cancelSendDraft('${id}')">取消示例方案</button>`}<button class="primary" onclick="closeModal();navigate('files')">查看成果库</button></div>`)};
sendRightHtml=function(){let s=privateAgent.send,b=s.brief;return `<div class="eyebrow">SAY IT / WE PREPARE IT</div><h2>你说需求，员工准备</h2><p class="intro">自动理解触达目标，整理一整套方案，再交给你确认。</p><div class="pa-side-flow">${[['message-square-text','你说一句需求'],['sparkles','自动准备内容与范围'],['scan-eye','你查看整套预览'],['check-check','确认后进入下一步']].map(([ic,t],i)=>`<div class="${b&&i<3?'ready':''}">${icon(ic)}<span>${t}</span></div>`).join('')}</div><div class="private-summary"><h4>当前上下文</h4><div class="kv"><span>企业</span><b>${demoCorp().name}</b></div><div class="kv"><span>客户渠道</span><b>企微客户 1 对 1 私聊</b></div><div class="kv"><span>员工关联</span><b>按客户归属自动匹配</b></div>${b?`<div class="kv"><span>当前版本</span><b>V${s.revision} · ${s.confirmedRevision===s.revision?'已确认':'待确认'}</b></div>`:''}</div><div class="pa-side-output"><h4>一并准备</h4><p>${icon('users-round')} 人群与门店范围</p><p>${icon('file-text')} 客户收到的文案</p><p>${icon('image')} 海报与图片预览</p><p>${icon('calendar-clock')} 确切发送时间</p></div><p class="private-side-meta">需要的业务信息优先从已绑定企业读取。缺少关键事实时，只在预览里标出待补充项，不让你重走配置流程。</p>`};
function paQueryRange(q,today=paToday()){let dates=[...q.matchAll(/20\d{2}-\d{2}-\d{2}/g)].map(m=>m[0]),start,end;if(dates.length){start=dates[0];end=dates[1]||dates[0]}else if(/昨天|昨日/.test(q)){start=end=paDateOffset(-1,today)}else if(/今天|今日/.test(q)){start=end=today}else if(/本月|这个月/.test(q)){start=today.slice(0,7)+'-01';end=today}else if(/上周/.test(q)){let weekday=new Date(today+'T12:00:00+08:00').getUTCDay()||7;start=paDateOffset(-weekday-6,today);end=paDateOffset(-weekday,today)}else{let n=Number(q.match(/(?:近|最近)(\d+)天/)?.[1]||7);start=paDateOffset(-Math.min(Math.max(n-1,0),365),today);end=today}return {start,end}}
statisticsWorkspace=function(){let s=privateAgent.query,p=privateState;return `${paInput('想了解哪一段运营表现？','直接说要查什么，统计范围、时间和维度由数字员工整理。',s.request,['上周各门店新增客户排行','本月客户增长和绑定情况','最近7天客户私聊群发的触达效果'],'queryPrivateByDemand','例如：帮我看上周各门店的拉新排行和绑定率。','paStatsRequest')}${s.error?`<div class="video-warning" role="alert">${esc(s.error)}</div>`:''}${s.summary?`<div class="pa-understood">${icon('sparkles')} 我理解为：${esc(s.summary)}</div>`:''}<div class="video-card" id="statsOutput">${p.statsResult?statsResultHtml():'<div class="pa-result-empty">'+icon('chart-no-axes-combined')+'<h3>说出问题后，直接给你结果</h3><p>时间、人群与指标口径会随结果一起展示，无需先填写报表参数。</p></div>'}</div><details class="pa-details"><summary>需要更精确？展开调整查询条件（可选）</summary><div class="form-grid"><div class="field"><label for="statsStart">开始日期</label><input id="statsStart" type="date" value="${p.start}" onchange="statsValue('start',this.value)"></div><div class="field"><label for="statsEnd">结束日期</label><input id="statsEnd" type="date" value="${p.end}" onchange="statsValue('end',this.value)"></div><div class="field"><label for="paStatType">查询内容</label><select id="paStatType" onchange="statsValue('statsType',this.value,true)">${selectOptions([['overview','客户总览'],['rank','运营排行'],['retention','留存趋势'],['groups','群聊统计'],['tasks','群发效果']],p.statsType)}</select></div><div class="field"><label for="rankDimension">统计维度</label><select id="rankDimension" onchange="statsValue('dimension',this.value)">${selectOptions([['station','门店'],['staff','员工'],['channel','渠道']],p.dimension)}</select></div></div><button class="secondary" onclick="runPrivateStats()">按调整后的条件查询示例</button></details>`};
function queryPrivateByDemand(text){let s=privateAgent.query,q=typeof text==='string'?text:$('#paStatsRequest').value.trim();if(!q){s.error='请说一下想了解的数据。';render();return}s.request=q;s.error='';privateState.statsResult=null;if(!/客户|新增|拉新|绑定|流失|留存|群|排行|运营/.test(q)||/成交|销售额|核销|利润|收入/.test(q)){s.summary='';s.error='当前私域统计支持客户增长、绑定、流失、留存和群发触达。成交、核销等经营数据需要对应业务数据，不能用客户数替代。';render();return}let r=paQueryRange(q);Object.assign(privateState,r,{statStaff:'',statsType:/触达|群发|送达/.test(q)?'tasks':/留存/.test(q)?'retention':/排行|排名|最多|最低|最高/.test(q)?'rank':/群聊|客户群|社群/.test(q)?'groups':'overview',dimension:/员工/.test(q)?'staff':/渠道/.test(q)?'channel':'station',metric:/绑定率/.test(q)?'rate':/流失/.test(q)?'lost':/绑定/.test(q)?'bound':'new',taskType:/群聊|客户群|群群发/.test(q)?'group':'customer',order:/最低|最少|低于/.test(q)?'asc':'desc'});s.summary=`${demoCorp().name} · ${r.start} 至 ${r.end} · ${privateState.statsType==='rank'?({station:'门店',staff:'员工',channel:'渠道'})[privateState.dimension]+'排行':({tasks:privateState.taskType==='customer'?'客户私聊群发效果':'客户群聊群发效果',groups:'群聊统计',retention:'留存趋势',overview:'客户总览'})[privateState.statsType]}。展示本地示例，不是实时业务查询。`;if(/排行.*和|排行.*及/.test(q))s.summary+='本次先呈现一个排行指标，可继续说“再看绑定率”。';runPrivateStats();paFocusResult('.pa-understood')}
groupsWorkspace=function(){let s=privateAgent.groups,p=privateState,all=groupMatches(),pages=Math.max(1,Math.ceil(all.length/p.groupSize));p.groupPage=Math.min(p.groupPage,pages);let rows=all.slice((p.groupPage-1)*p.groupSize,p.groupPage*p.groupSize);return `${paInput('想找哪个群，或者了解谁？','说出门店、群名或群主，我来定位相关群聊和成员信息。',s.request,['帮我找滨江店的会员群','看看员工乙负责哪些客户群','查一下活动运营分组里有哪些群'],'queryGroupsByDemand','例如：找一下滨江店的会员群，看看群主和成员。','paGroupsRequest')}${s.error?`<div class="video-warning">${esc(s.error)}</div>`:''}${s.summary?`<div class="pa-understood">${icon('sparkles')} ${esc(s.summary)}</div><div class="video-card"><h3>为你找到 ${all.length} 个示例群聊</h3>${table(['群聊','群主','成员数','操作'],rows.map(g=>[g.name,g.owner.name,g.members.length,`<button class="link" onclick="groupDetail('${g.id}','info')">查看群与成员 →</button>`]))}<div class="private-actions"><small>第 ${p.groupPage} / ${pages} 页</small><div><button class="secondary" ${p.groupPage===1?'disabled':''} onclick="privateState.groupPage--;render()">上一页</button> <button class="secondary" ${p.groupPage>=pages?'disabled':''} onclick="privateState.groupPage++;render()">下一页</button></div></div></div>`:'<div class="video-card pa-result-empty">'+icon('messages-square')+'<h3>不用先设置群主和分组</h3><p>把你想找的群说出来，我会把匹配依据和结果一起列出。</p></div>'}<details class="pa-details"><summary>展开精细筛选（可选）</summary><div class="form-grid"><div class="field"><label for="groupKeyword">群名关键词</label><input id="groupKeyword" value="${esc(p.groupKeyword)}"></div><div class="field"><label for="groupOwner">群主</label><select id="groupOwner" onchange="setGroupFilter('groupOwner',this.value)">${selectOptions([['','全部'],...demoStaff().map(e=>[e.id,e.name])],p.groupOwner)}</select></div></div><button class="secondary" onclick="privateAgent.groups.summary='按你调整后的条件匹配示例群聊。';searchGroups()">更新查询</button></details>`};
function queryGroupsByDemand(text){let s=privateAgent.groups,q=typeof text==='string'?text:$('#paGroupsRequest').value.trim();if(!q){s.error='请说一下想找的群聊。';render();return}s.request=q;s.error='';privateState.groupKeyword='';privateState.groupOwner='';privateState.groupClass='';privateState.groupPage=1;let station=demoCorp().stations.find(n=>q.includes(n)||q.includes(n.replace('店',''))),staff=demoStaff().find(e=>q.includes(e.name)),cls=['活动运营','会员服务'].find(x=>q.includes(x));if(!/群|社群/.test(q)&&!station&&!staff){s.summary='';s.error='请补充想查询的群聊、门店或群主，例如“滨江店的会员群”。';render();return}if(paUnknownStation(q)){s.summary='';s.error='当前企业未匹配到指定门店，不会自动改查全部群聊。';render();return}if(/删除|解散|移除|踢|修改公告|发消息/.test(q)){s.summary='';s.error='群聊查询为只读能力，无法修改、解散群聊或向群内发送消息。';render();return}if(station)privateState.groupKeyword=station;if(staff)privateState.groupOwner=String(staff.id);if(cls)privateState.groupClass=cls;if(/会员群/.test(q))privateState.groupClass='会员服务';s.summary=`${demoCorp().name} · ${[station,staff?.name,cls].filter(Boolean).join(' / ')||'全部示例群聊'}，展示群主、群成员与分组。`;privateLog('按一句话查询群聊（示例）：'+q);render();paFocusResult('.pa-understood')}
qaWorkspace=function(){let old=legacyPrivate.qa();let first=old.indexOf('<div class="video-card">'),directory=old.indexOf('<div class="panel-label">');return `<div class="pa-agent-heading"><div class="avatar">${icon('book-open-text')}</div><div><h2>运营问题，直接问我</h2><p>一句话描述问题，数字员工整理答案、来源或需要补充的知识。</p></div></div>`+old.slice(first,directory)+`<details class="pa-details"><summary>查看运营知识目录（可选）</summary>${old.slice(directory)}</details>`};
